window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1b93ee8ba6fe204e"]={"versions": [{"id": "FIG-1b93ee8ba6fe204e", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Synchronisationszeitbedingungen im Metamodell der AUTOSAR Adaptive Platform Timing Extensions (<code>AUTOSAR_TPS_AdaptivePlatformTimingExtensions</code>). Es definiert die strukturelle Einbettung von <code>SynchronizationTimingConstraint</code> in das Timing-Modell über die Spezialisierung von <code>TimingConstraint</code> sowie Beziehungen zu Ablaufketten (<code>TimingDescriptionEventChain</code>) und Zeitdarstellungen (<code>MultidimensionalTime</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>SynchronizationTimingConstraint</code>, spezialisiert aus <code>TimingConstraint</code> (mit den Stereotypen bzw. Eigenschaften <code>Identifiable</code> und <code>Traceable</code>). Sie besitzt zwei Attribute:</p>\n<ul class=\"fig-list\">\n<li><code>eventOccurrenceKind: EventOccurrenceKindEnum [0..1]</code></li>\n<li><code>synchronizationConstraintType: SynchronizationTypeEnum</code> (obligatorisch)</li>\n</ul>\n<p class=\"fig-p\">Assoziationen und Kompositionen:</p>\n<ul class=\"fig-list\">\n<li>Gerichtet-assoziierte Zielklasse <code>TimingDescriptionEventChain</code> (im Namensraum <code>TimingDescription</code>, kursiv) über die Rolle <code>+scope</code> mit Multiplizität <code>0..*</code>.</li>\n<li>Strenge Komposition (<code>+tolerance 1</code>) der Klasse <code>MultidimensionalTime</code> mit den obligatorischen Attributen <code>cseCode: CseCodeType</code> und <code>cseCodeFactor: Integer</code>.</li>\n</ul>\n<p class=\"fig-p\">Verwendete Enumerationen:</p>\n<ul class=\"fig-list\">\n<li><code>EventOccurrenceKindEnum</code> mit den Literalen <code>singleOccurrence</code> und <code>multipleOccurrences</code>.</li>\n<li><code>SynchronizationTypeEnum</code> mit den Literalen <code>stimulusSynchronization</code> und <code>responseSynchronization</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Ablauf- oder Sequenzdarstellung. Die Semantik betrifft die zeitliche Synchronisation korrespondierender Ereignisse: Entweder Stimuli (<code>stimulusSynchronization</code>) oder Antworten (<code>responseSynchronization</code>) über eine Menge von referenzierten Event Chains (<code>scope</code>) müssen innerhalb der über <code>tolerance</code> fest vorgegebenen multidimensionalen Zeittoleranz synchron auftreten. Das Attribut <code>eventOccurrenceKind</code> steuert, ob einzelne oder mehrfache Vorkommnisse betrachtet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler müssen beachten, dass <code>SynchronizationTimingConstraint</code> von <code>Identifiable</code> und <code>Traceable</code> erbt und somit eindeutige Bezeichner sowie Rückverfolgbarkeit erfordert. <code>synchronizationConstraintType</code> und die Zusammensetzung von <code>tolerance</code> sind zwingend erforderlich (Multiplizität jeweils 1 bzw. implizit 1). Für <code>MultidimensionalTime</code> müssen <code>cseCode</code> und <code>cseCodeFactor</code> vollständig spezifiziert werden. Die Einschränkung kann auf null bis beliebig viele Event Chains angewendet werden (<code>0..*</code>).</p>"}, {"id": "FIG-4d5c95d45d9e71ec", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Synchronisationszeitbedingungen im Metamodell der AUTOSAR Adaptive Platform Timing Extensions (<code>AUTOSAR_TPS_AdaptivePlatformTimingExtensions</code>). Es definiert die strukturelle Einbettung von <code>SynchronizationTimingConstraint</code> in das Timing-Modell über die Spezialisierung von <code>TimingConstraint</code> sowie Beziehungen zu Ablaufketten (<code>TimingDescriptionEventChain</code>) und Zeitdarstellungen (<code>MultidimensionalTime</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>SynchronizationTimingConstraint</code>, spezialisiert aus <code>TimingConstraint</code> (mit den Stereotypen bzw. Eigenschaften <code>Identifiable</code> und <code>Traceable</code>). Sie besitzt zwei Attribute:</p>\n<ul class=\"fig-list\">\n<li><code>eventOccurrenceKind: EventOccurrenceKindEnum [0..1]</code></li>\n<li><code>synchronizationConstraintType: SynchronizationTypeEnum</code> (obligatorisch)</li>\n</ul>\n<p class=\"fig-p\">Assoziationen und Kompositionen:</p>\n<ul class=\"fig-list\">\n<li>Gerichtet-assoziierte Zielklasse <code>TimingDescriptionEventChain</code> (im Namensraum <code>TimingDescription</code>, kursiv) über die Rolle <code>+scope</code> mit Multiplizität <code>0..*</code>.</li>\n<li>Strenge Komposition (<code>+tolerance 1</code>) der Klasse <code>MultidimensionalTime</code> mit den obligatorischen Attributen <code>cseCode: CseCodeType</code> und <code>cseCodeFactor: Integer</code>.</li>\n</ul>\n<p class=\"fig-p\">Verwendete Enumerationen:</p>\n<ul class=\"fig-list\">\n<li><code>EventOccurrenceKindEnum</code> mit den Literalen <code>singleOccurrence</code> und <code>multipleOccurrences</code>.</li>\n<li><code>SynchronizationTypeEnum</code> mit den Literalen <code>stimulusSynchronization</code> und <code>responseSynchronization</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Ablauf- oder Sequenzdarstellung. Die Semantik betrifft die zeitliche Synchronisation korrespondierender Ereignisse: Entweder Stimuli (<code>stimulusSynchronization</code>) oder Antworten (<code>responseSynchronization</code>) über eine Menge von referenzierten Event Chains (<code>scope</code>) müssen innerhalb der über <code>tolerance</code> fest vorgegebenen multidimensionalen Zeittoleranz synchron auftreten. Das Attribut <code>eventOccurrenceKind</code> steuert, ob einzelne oder mehrfache Vorkommnisse betrachtet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler müssen beachten, dass <code>SynchronizationTimingConstraint</code> von <code>Identifiable</code> und <code>Traceable</code> erbt und somit eindeutige Bezeichner sowie Rückverfolgbarkeit erfordert. <code>synchronizationConstraintType</code> und die Zusammensetzung von <code>tolerance</code> sind zwingend erforderlich (Multiplizität jeweils 1 bzw. implizit 1). Für <code>MultidimensionalTime</code> müssen <code>cseCode</code> und <code>cseCodeFactor</code> vollständig spezifiziert werden. Die Einschränkung kann auf null bis beliebig viele Event Chains angewendet werden (<code>0..*</code>).</p>"}, {"id": "FIG-8e626b98dc322dda", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Synchronisationszeitbedingungen im Metamodell der AUTOSAR Adaptive Platform Timing Extensions (<code>AUTOSAR_TPS_AdaptivePlatformTimingExtensions</code>). Es definiert die strukturelle Einbettung von <code>SynchronizationTimingConstraint</code> in das Timing-Modell über die Spezialisierung von <code>TimingConstraint</code> sowie Beziehungen zu Ablaufketten (<code>TimingDescriptionEventChain</code>) und Zeitdarstellungen (<code>MultidimensionalTime</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>SynchronizationTimingConstraint</code>, spezialisiert aus <code>TimingConstraint</code> (<code>Identifiable</code>, <code>Traceable</code>). Attribute:</p>\n<ul class=\"fig-list\">\n<li><code>eventOccurrenceKind: EventOccurrenceKindEnum [0..1]</code></li>\n<li><code>synchronizationConstraintType: SynchronizationTypeEnum [0..1]</code></li>\n</ul>\n<p class=\"fig-p\">Assoziationen und Kompositionen:</p>\n<ul class=\"fig-list\">\n<li>Gerichtet-assoziierte Zielklasse <code>TimingDescriptionEventChain</code> (im Kontext <code>TimingDescription</code>) über die Rolle <code>+scope</code> mit Kardinalität <code>0..*</code>. Die Klasse besitzt das optionale Attribut <code>+ isPipeliningPermitted: Boolean [0..1]</code>.</li>\n<li>Komposition <code>+tolerance 0..1</code> auf <code>MultidimensionalTime</code>. <code>MultidimensionalTime</code> enthält die Attribute <code>+ cseCode: CseCodeType [0..1]</code> und <code>+ cseCodeFactor: Integer [0..1]</code>.</li>\n</ul>\n<p class=\"fig-p\">Enumerationen:</p>\n<ul class=\"fig-list\">\n<li><code>EventOccurrenceKindEnum</code>: <code>singleOccurrence</code>, <code>multipleOccurrences</code>.</li>\n<li><code>SynchronizationTypeEnum</code>: <code>stimulusSynchronization</code>, <code>responseSynchronization</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Ablauf- oder Sequenzdarstellung. Die Semantik betrifft die zeitliche Synchronisation korrespondierender Ereignisse: Entweder Stimuli (<code>stimulusSynchronization</code>) oder Antworten (<code>responseSynchronization</code>) über eine Menge von referenzierten Event Chains (<code>scope</code>) müssen innerhalb der über <code>tolerance</code> fest vorgegebenen multidimensionalen Zeittoleranz synchron auftreten. Das Attribut <code>eventOccurrenceKind</code> steuert, ob einzelne oder mehrfache Vorkommnisse betrachtet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>synchronizationConstraintType</code> sowie die Kompositionsrolle <code>+tolerance</code> sind optional (<code>[0..1]</code> bzw. <code>0..1</code>). Auch innerhalb von <code>MultidimensionalTime</code> sind <code>cseCode</code> und <code>cseCodeFactor</code> optionalisierbar (<code>[0..1]</code>). Die referenzierte <code>TimingDescriptionEventChain</code> kann über <code>isPipeliningPermitted</code> explizit steuern, ob überlappende bzw. pipelined Kettenausführungen zulässig sind. Modellierungs- und Validierungswerkzeuge müssen fehlende Toleranzangaben oder Constraint-Typen abfangen bzw. Standardwerte ansetzen.</p>"}], "trans": [{"from": "FIG-1b93ee8ba6fe204e", "to": "FIG-4d5c95d45d9e71ec", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Package-Präfixe <code>TimingConstraint::</code>, <code>TimingDescription::</code> und <code>MultidimensionalTime::</code> vor den Klassennamen in den Kopfzeilen der Klassen <code>TimingConstraint</code>, <code>TimingDescriptionEventChain</code> und <code>MultidimensionalTime</code> entfernt.</li>\n</ul>"}, {"from": "FIG-4d5c95d45d9e71ec", "to": "FIG-8e626b98dc322dda", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>In <code>SynchronizationTimingConstraint</code>: Multiplizität des Attributs <code>synchronizationConstraintType</code> von <code>[1]</code> auf <code>[0..1]</code> geändert.</li>\n<li>In <code>SynchronizationTimingConstraint</code>: Multiplizität der Kompositionsrolle <code>+tolerance</code> zu <code>MultidimensionalTime</code> von <code>1</code> auf <code>0..1</code> geändert.</li>\n<li>In <code>MultidimensionalTime</code>: Multiplizität der Attribute <code>cseCode</code> und <code>cseCodeFactor</code> jeweils von <code>[1]</code> auf <code>[0..1]</code> geändert.</li>\n<li>In <code>TimingDescriptionEventChain</code>: Attribut <code>+ isPipeliningPermitted: Boolean [0..1]</code> ergänzt.</li>\n</ul>"}]};
